def matrixScore(grid: list[list[int]]) -> int:
    R, C = len(grid), len(grid[0])
    # Flip any row whose first element is 0
    for r in range(R):
        if grid[r][0] == 0:
            for c in range(C): grid[r][c] ^= 1
    ans = 0
    for c in range(C):
        col_ones = sum(grid[r][c] for r in range(R))
        best_ones = max(col_ones, R - col_ones)
        ans += best_ones * (1 << (C - 1 - c))
    return ans

